using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.NTF.TiposNotificacion;namespace GraphApi.Services.NTF.TiposNotificacion{    public class TiposNotificacionService : ITiposNotificacionService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public TiposNotificacionService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadTiposNotificacion>> GetTiposNotificacions(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM ntf.TiposNotificacion (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadTiposNotificacion>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetTiposNotificacionsDynamic(            int? tipoNotificacionID,            string? tipoNotiicfacion,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "TipoNotificacionID, TipoNotiicfacion, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM ntf.TiposNotificacion (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (tipoNotificacionID.HasValue)            {                vSql.Append(" AND TipoNotificacionID = @TipoNotificacionID");                vParameters.Add("TipoNotificacionID",tipoNotificacionID);            }            if (!string.IsNullOrWhiteSpace(tipoNotiicfacion))            {                vSql.Append(" AND TipoNotiicfacion LIKE @TipoNotiicfacion");                vParameters.Add("TipoNotiicfacion",$"%{tipoNotiicfacion}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadTiposNotificacion> CreateTiposNotificacion(clCreateTiposNotificacion objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO ntf.TiposNotificacion                (TipoNotiicfacion, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@TipoNotiicfacion, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.TipoNotiicfacion,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT TipoNotificacionID, TipoNotiicfacion, bEliminado                FROM ntf.TiposNotificacion (NOLOCK)                WHERE TipoNotificacionID = @TipoNotificacionID;";            var vReadParams = new { TipoNotificacionID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadTiposNotificacion>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el TiposNotificacion con ID {vNewId}.");            return vCreated;        }        public async Task<clReadTiposNotificacion?> UpdateTiposNotificacion(clUpdateTiposNotificacion objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("TipoNotificacionID", objInput.TipoNotificacionID);            if (objInput.TipoNotiicfacion is not null)            {                vSets.Add("TipoNotiicfacion = @TipoNotiicfacion");                vParameters.Add("TipoNotiicfacion", objInput.TipoNotiicfacion);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE ntf.TiposNotificacion                SET {vSetClause}                WHERE TipoNotificacionID = @TipoNotificacionID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT TipoNotificacionID, TipoNotiicfacion, bEliminado                FROM ntf.TiposNotificacion (NOLOCK)                WHERE TipoNotificacionID = @TipoNotificacionID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadTiposNotificacion>(sSelect, new {  objInput.TipoNotificacionID });        }        public async Task<bool> DeleteTiposNotificacion(int nTiposNotificacionID)        {            const string sSql = @"                DELETE FROM ntf.TiposNotificacion                WHERE TipoNotificacionID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nTiposNotificacionID });            return vAffected > 0;        }    }}